window.QBANK["m2w2"] = [
  {"level": 1, "q": "Messages API của Claude có tự lưu lịch sử hội thoại giữa các request không?", "options": ["Không, API là stateless; client phải gửi lại toàn bộ lịch sử trong mỗi request", "Có, API lưu 24 giờ theo API key", "Có, nếu truyền thêm tham số conversation_id", "Chỉ lưu khi bật streaming"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Mỗi request là độc lập, ngữ cảnh chỉ gồm những gì bạn gửi trong <code>messages</code> và <code>system</code>.<br><strong>Vì sao các lựa chọn khác sai:</strong> Messages API không có cơ chế lưu theo API key hay tham số <code>conversation_id</code>; streaming chỉ đổi cách truyền output, không làm API nhớ hội thoại."},
  {"level": 1, "q": "Trong mảng <code>messages</code> của một hội thoại thông thường, hai role nào xen kẽ nhau?", "options": ["<code>human</code> và <code>ai</code>", "<code>user</code> và <code>bot</code>", "<code>client</code> và <code>server</code>", "<code>user</code> và <code>assistant</code>"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Messages API dùng role <code>user</code> cho người dùng (và tool_result) và <code>assistant</code> cho câu trả lời của Claude, xen kẽ nhau.<br><strong>Vì sao các lựa chọn khác sai:</strong> <code>human</code>/<code>ai</code>, <code>bot</code>, <code>client</code>/<code>server</code> không phải role hợp lệ của Messages API."},
  {"level": 1, "q": "Trong TypeScript, sau khi nhận <code>message</code> từ API, bạn nên push gì vào <code>history</code>?<pre><code>const message = await client.messages.create({ model: \"claude-opus-5\", max_tokens: 16000, messages: history });\nhistory.push({ role: \"assistant\", content: /* ? */ });</code></pre>", "options": ["<code>message.content[0].text</code>", "<code>message.content</code> (nguyên mảng content block)", "<code>message.usage</code>", "<code>message.id</code>"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Content có thể chứa block <code>thinking</code>, <code>tool_use</code>…; nối nguyên mảng mới giữ đúng trạng thái cho lượt sau.<br><strong>Vì sao các lựa chọn khác sai:</strong> Chỉ lấy text của block đầu làm mất các block khác và có thể sai nếu block đầu không phải text; <code>usage</code> là số liệu thống kê; <code>id</code> chỉ là mã định danh message."},
  {"level": 1, "q": "Streaming của Claude API truyền output về client theo định dạng nào?", "options": ["WebSocket hai chiều", "Server-Sent Events (SSE)", "gRPC bidirectional stream", "Long polling mỗi 1 giây"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Khi stream, API trả một chuỗi sự kiện SSE qua HTTP như <code>message_start</code>, <code>content_block_delta</code>, <code>message_stop</code>.<br><strong>Vì sao các lựa chọn khác sai:</strong> API không mở WebSocket hay gRPC, và client không phải poll định kỳ; SDK đọc luồng SSE trên một kết nối HTTP."},
  {"level": 1, "q": "So với gọi không streaming, giá token khi dùng streaming thế nào?", "options": ["Rẻ hơn khoảng 50%", "Đắt hơn vì giữ kết nối lâu", "Miễn phí token output", "Như nhau, streaming không thay đổi cách tính tiền"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Streaming chỉ thay đổi cách truyền dữ liệu; số token input/output và đơn giá không đổi.<br><strong>Vì sao các lựa chọn khác sai:</strong> Giảm giá 50% là của Message Batches API chứ không phải streaming; kết nối dài không tính phụ phí; token output luôn bị tính."},
  {"level": 1, "q": "Trong SDK TypeScript, cách đăng ký nhận từng đoạn chữ khi stream là gì?", "options": ["<code>stream.on(\"chunk\", (delta) =&gt; ...)</code>", "<code>stream.onData((delta) =&gt; ...)</code>", "<code>for (const t of stream.text_stream)</code>", "<code>stream.on(\"text\", (delta) =&gt; ...)</code>"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> <code>MessageStream</code> phát sự kiện <code>\"text\"</code> với từng đoạn text mới được sinh.<br><strong>Vì sao các lựa chọn khác sai:</strong> Không có sự kiện <code>\"chunk\"</code> hay phương thức <code>onData</code>; <code>text_stream</code> là thuộc tính của SDK Python, không phải TypeScript."},
  {"level": 1, "q": "Trong SDK Python, thuộc tính nào dùng để lặp qua từng đoạn chữ khi stream?", "options": ["<code>stream.chunks</code>", "<code>stream.iter_text()</code>", "<code>stream.text_stream</code>", "<code>stream.events_text</code>"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Trong khối <code>with client.messages.stream(...) as stream:</code>, <code>for text in stream.text_stream</code> trả từng đoạn text.<br><strong>Vì sao các lựa chọn khác sai:</strong> <code>chunks</code>, <code>iter_text()</code> và <code>events_text</code> không phải API của SDK Python cho Messages streaming."},
  {"level": 1, "q": "Trong SDK Python, sau khi stream xong, gọi hàm nào để lấy message hoàn chỉnh kèm <code>usage</code>?", "options": ["<code>stream.result()</code>", "<code>stream.finalMessage()</code>", "<code>stream.get_final_message()</code>", "<code>client.messages.retrieve(id)</code>"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> <code>get_final_message()</code> trả Message đầy đủ gồm content, stop_reason và usage.<br><strong>Vì sao các lựa chọn khác sai:</strong> <code>result()</code> không tồn tại; <code>finalMessage()</code> là tên trong SDK TypeScript; Messages API không có endpoint lấy lại message theo id."},
  {"level": 1, "q": "Sự kiện SSE nào báo stream đã kết thúc hoàn toàn?", "options": ["<code>content_block_stop</code>", "<code>message_stop</code>", "<code>message_delta</code>", "<code>ping</code>"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> <code>message_stop</code> là sự kiện cuối cùng của một message được stream.<br><strong>Vì sao các lựa chọn khác sai:</strong> <code>content_block_stop</code> chỉ kết thúc một block; <code>message_delta</code> mang stop_reason và usage nhưng vẫn chưa phải sự kiện cuối; <code>ping</code> chỉ giữ kết nối."},
  {"level": 1, "q": "Mảnh text mới khi stream nằm trong sự kiện nào?", "options": ["<code>message_start</code> với <code>delta.text</code>", "<code>content_block_delta</code> với <code>delta.type === \"text_delta\"</code>", "<code>content_block_start</code> với <code>type === \"text\"</code>", "<code>message_delta</code> với <code>delta.text</code>"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Mỗi đoạn chữ đến dưới dạng <code>content_block_delta</code> có delta kiểu <code>text_delta</code>.<br><strong>Vì sao các lựa chọn khác sai:</strong> <code>message_start</code> chỉ mở đầu message; <code>content_block_start</code> báo một block mới bắt đầu (thường rỗng); <code>message_delta</code> mang stop_reason và usage chứ không mang text."},
  {"level": 1, "q": "Vì sao SDK yêu cầu dùng streaming khi <code>max_tokens</code> rất lớn?", "options": ["Vì API tính giá thấp hơn khi stream", "Request sinh output dài dễ vượt timeout HTTP nếu phải chờ toàn bộ", "Vì không stream thì max_tokens bị giới hạn ở 1.024", "Vì model chỉ suy nghĩ khi stream"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Output dài có thể mất nhiều phút; streaming giữ kết nối có dữ liệu liên tục nên tránh bị cắt do timeout.<br><strong>Vì sao các lựa chọn khác sai:</strong> Giá không đổi khi stream; giới hạn max_tokens không phải 1.024; thinking hoạt động cả khi stream lẫn không stream."},
  {"level": 1, "q": "Streaming cải thiện rõ nhất chỉ số nào?", "options": ["Thời gian tới chữ đầu tiên (độ trễ người dùng cảm nhận)", "Tổng số token output", "Chi phí mỗi request", "Độ chính xác của câu trả lời"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Người dùng thấy chữ gần như ngay khi Claude bắt đầu sinh, thay vì chờ cả câu trả lời.<br><strong>Vì sao các lựa chọn khác sai:</strong> Số token và chi phí giữ nguyên; chất lượng câu trả lời không phụ thuộc cách truyền."},
  {"level": 1, "q": "Header <code>Content-Type</code> chuẩn khi server của bạn trả Server-Sent Events cho trình duyệt là gì?", "options": ["<code>application/json</code>", "<code>text/event-stream</code>", "<code>application/octet-stream</code>", "<code>multipart/mixed</code>"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> SSE dùng MIME type <code>text/event-stream</code>; <code>EventSource</code> của trình duyệt yêu cầu đúng kiểu này.<br><strong>Vì sao các lựa chọn khác sai:</strong> <code>application/json</code> là một tài liệu JSON trọn vẹn; <code>octet-stream</code> là dữ liệu nhị phân chung; <code>multipart/mixed</code> không phải định dạng SSE."},
  {"level": 1, "q": "Quản lý lịch sử theo kiểu \"append-only\" nghĩa là gì?", "options": ["Chỉ giữ lượt mới nhất", "Sửa lượt cũ khi người dùng đổi ý", "Chỉ nối thêm lượt mới vào cuối, không sửa hay sắp xếp lại lượt cũ", "Đảo ngược thứ tự để lượt mới lên đầu"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Append-only giữ nguyên tiền tố của hội thoại; lượt mới luôn được thêm vào cuối.<br><strong>Vì sao các lựa chọn khác sai:</strong> Chỉ giữ lượt mới nhất làm Claude quên ngữ cảnh; sửa lượt cũ hay đảo thứ tự làm thay đổi tiền tố và phá cache."},
  {"level": 1, "q": "Vì sao lịch sử append-only giúp prompt caching hiệu quả?", "options": ["Vì API chỉ cache lượt cuối cùng", "Vì cache tự bỏ qua khác biệt nhỏ trong lượt cũ", "Vì append-only làm giảm token output", "Cache khớp theo tiền tố giống hệt từng byte, nên phần đầu không đổi sẽ được đọc từ cache"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Prompt caching là so khớp tiền tố; chỉ cần một byte ở đầu thay đổi là mọi phần phía sau mất cache.<br><strong>Vì sao các lựa chọn khác sai:</strong> Cache không chỉ áp dụng cho lượt cuối; nó không \"bỏ qua\" khác biệt; token output không liên quan tới cách quản lý lịch sử."},
  {"level": 1, "q": "Ngoài <code>text</code>, loại content block nào có thể xuất hiện trong <code>response.content</code> và cần giữ khi nối lịch sử?", "options": ["<code>html</code> và <code>markdown</code>", "<code>audio</code> và <code>video</code>", "<code>thinking</code> và <code>tool_use</code>", "Không có, response chỉ chứa text"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Khi bật thinking hoặc dùng tool, content chứa thêm block <code>thinking</code>, <code>tool_use</code>; chúng mang trạng thái cần cho lượt sau.<br><strong>Vì sao các lựa chọn khác sai:</strong> Không có block <code>html</code>, <code>markdown</code>, <code>audio</code>, <code>video</code> trong output Messages API; nói response chỉ có text là sai khi dùng thinking/tool."},
  {"level": 1, "q": "Hội thoại quá dài làm request tốn nhiều token input. Nhóm kỹ thuật nào xử lý đúng vấn đề này?", "options": ["Tăng <code>max_tokens</code>", "Tóm tắt lượt cũ, compaction hoặc context editing", "Chuyển sang streaming", "Gửi lại mỗi lượt hai lần cho chắc"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Các kỹ thuật này giảm lượng ngữ cảnh phải gửi lại mà vẫn giữ thông tin quan trọng.<br><strong>Vì sao các lựa chọn khác sai:</strong> <code>max_tokens</code> giới hạn output chứ không giảm input; streaming không đổi số token; gửi lặp chỉ làm tốn gấp đôi."},
  {"level": 1, "q": "Trong Next.js App Router (monorepo <code>apps/web</code>), route handler cho <code>POST /api/chat</code> đặt ở đâu?", "options": ["<code>apps/web/app/api/chat/route.ts</code> với <code>export async function POST(req: Request)</code>", "<code>apps/web/app/api/chat/page.tsx</code> với <code>export default</code>", "<code>apps/web/pages/api/chat/route.ts</code> với <code>export const POST</code> trong Pages Router", "<code>apps/web/app/api/chat/controller.ts</code> với decorator <code>@Post()</code>"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> App Router dùng file <code>route.ts</code> trong thư mục <code>app/</code> và export hàm theo tên HTTP method.<br><strong>Vì sao các lựa chọn khác sai:</strong> <code>page.tsx</code> là trang UI, không phải API; thư mục <code>pages/api</code> thuộc Pages Router với quy ước khác; <code>@Post()</code> là decorator NestJS."},
  {"level": 1, "q": "NestJS dùng decorator nào để tạo endpoint Server-Sent Events?", "options": ["<code>@Stream()</code>, handler trả về <code>ReadableStream</code>", "<code>@EventSource()</code>, handler trả về mảng chuỗi", "<code>@Get({ stream: true })</code>, handler trả về Promise", "<code>@Sse()</code>, handler trả về <code>Observable&lt;MessageEvent&gt;</code>"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> NestJS có decorator <code>@Sse(path)</code>; mỗi giá trị Observable phát ra là một sự kiện SSE.<br><strong>Vì sao các lựa chọn khác sai:</strong> <code>@Stream()</code>, <code>@EventSource()</code> và tuỳ chọn <code>stream: true</code> không phải API của NestJS."},
  {"level": 1, "q": "Giá trị <code>stop_reason</code> nào nghĩa là Claude kết thúc câu trả lời một cách tự nhiên?", "options": ["<code>end_turn</code>", "<code>max_tokens</code>", "<code>stop_sequence</code>", "<code>tool_use</code>"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> <code>end_turn</code> báo Claude đã nói xong theo ý mình.<br><strong>Vì sao các lựa chọn khác sai:</strong> <code>max_tokens</code> là bị cắt do chạm trần output; <code>stop_sequence</code> là gặp chuỗi dừng bạn đặt; <code>tool_use</code> là Claude đang chờ kết quả tool."},
  {"level": 1, "q": "Stream kết thúc với <code>stop_reason: \"max_tokens\"</code>. Điều đó cho biết gì?", "options": ["Claude đã trả lời xong", "Câu trả lời bị cắt vì chạm giới hạn token output", "Input vượt context window", "Stream bị lỗi mạng"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> <code>max_tokens</code> nghĩa là output bị dừng vì đạt trần <code>max_tokens</code>, nội dung có thể dở dang.<br><strong>Vì sao các lựa chọn khác sai:</strong> Trả lời xong là <code>end_turn</code>; input quá dài bị lỗi 400 chứ không có stop_reason; lỗi mạng làm stream báo lỗi, không trả stop_reason."},
  {"level": 1, "q": "Khi stream, số <code>output_tokens</code> cuối cùng lấy ở đâu?", "options": ["Chỉ trong header HTTP của response", "Trong sự kiện <code>message_delta</code> gần cuối, và trong message hoàn chỉnh từ <code>finalMessage()</code>", "Trong <code>message_start</code>, đã chính xác ngay từ đầu", "Không có, stream không trả usage"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Usage output được cập nhật ở <code>message_delta</code>; helper <code>finalMessage()</code>/<code>get_final_message()</code> gom lại vào <code>usage</code>.<br><strong>Vì sao các lựa chọn khác sai:</strong> Header HTTP không chứa usage; <code>message_start</code> chưa biết output cuối; stream vẫn trả usage đầy đủ."},
  {"level": 1, "q": "Trong SDK TypeScript, muốn dừng một stream đang chạy (ví dụ người dùng bấm \"Dừng\"), bạn gọi gì?", "options": ["<code>stream.close()</code>", "<code>stream.abort()</code>", "<code>client.messages.cancel(message.id)</code>", "Không dừng được, phải chờ hết"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> <code>MessageStream</code> có phương thức <code>abort()</code> để huỷ request HTTP đang chạy.<br><strong>Vì sao các lựa chọn khác sai:</strong> <code>close()</code> không phải API của MessageStream; Messages API không có endpoint cancel theo id; stream hoàn toàn dừng được."},
  {"level": 1, "q": "Lưu content của mỗi lượt vào PostgreSQL qua Prisma, kiểu cột nào phù hợp nhất?<pre><code>model Message {\n  id             String   @id @default(cuid())\n  conversationId String\n  role           String\n  content        ???\n  createdAt      DateTime @default(now())\n}</code></pre>", "options": ["<code>Json</code> (jsonb trong PostgreSQL) để lưu nguyên mảng content block", "<code>String @db.VarChar(255)</code>", "<code>Int</code>", "<code>Boolean</code>"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Content là mảng block có cấu trúc (text, thinking, tool_use…); cột Json lưu nguyên vẹn để gửi lại API.<br><strong>Vì sao các lựa chọn khác sai:</strong> VarChar(255) quá ngắn và làm mất cấu trúc; Int và Boolean không biểu diễn được nội dung hội thoại."},
  {"level": 1, "q": "Cần tóm tắt 10 lượt hội thoại cũ với chi phí thấp. Model nào hợp lý nhất?", "options": ["<code>claude-opus-5</code> với <code>effort: \"max\"</code>", "<code>claude-sonnet-5</code> với <code>max_tokens: 64000</code>", "<code>claude-haiku-4-5</code>", "Không cần model: xoá 10 lượt đầu vẫn giữ đủ dữ kiện"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Tóm tắt là việc đơn giản; Haiku rẻ và nhanh, phù hợp chạy nền.<br><strong>Vì sao các lựa chọn khác sai:</strong> Opus với effort max tốn chi phí không cần thiết; max_tokens lớn không làm tóm tắt tốt hơn; xoá thẳng làm mất dữ kiện như tên, gói dịch vụ."},
  {"level": 1, "q": "Response có block <code>tool_use</code>. Lượt <code>user</code> tiếp theo phải chứa gì?", "options": ["Một chuỗi text \"Kết quả: ...\"", "Block <code>tool_use</code> giống hệt để xác nhận", "Block <code>tool_result</code> có <code>tool_use_id</code> trùng với id của tool_use", "Không cần gì, gửi câu hỏi mới là được"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> API ghép kết quả với lời gọi tool qua <code>tool_use_id</code>; thiếu tool_result tương ứng thì request bị từ chối.<br><strong>Vì sao các lựa chọn khác sai:</strong> Text thuần không liên kết với lời gọi tool; user không gửi block tool_use; bỏ qua tool_result làm lịch sử không hợp lệ."},
  {"level": 1, "q": "Khi nối block <code>thinking</code> trở lại lịch sử, cần làm gì?", "options": ["Giữ nguyên block, không sửa nội dung hay chữ ký", "Xoá đi vì không cần nữa", "Rút gọn nội dung cho đỡ tốn token", "Đổi thành block text"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Block thinking có chữ ký (signature) để API kiểm tra; sửa hoặc đổi kiểu làm block không còn hợp lệ.<br><strong>Vì sao các lựa chọn khác sai:</strong> Xoá thinking có thể làm mất trạng thái suy luận, nhất là trong vòng tool use; rút gọn hay đổi thành text đều là sửa nội dung đã ký."},
  {"level": 1, "q": "Trường hợp nào lợi ích \"hiện chữ sớm\" của streaming gần như không có ý nghĩa?", "options": ["Job nền đọc từ SQS lúc nửa đêm, kết quả ghi vào database, không ai xem trực tiếp", "Chatbot hỗ trợ khách hàng trên web", "Trợ lý viết email hiển thị chữ trong lúc soạn", "Màn hình giải thích code trong IDE nội bộ"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Không có người chờ nên độ trễ cảm nhận không quan trọng; streaming lúc này chỉ còn lợi ích tránh timeout với output dài.<br><strong>Vì sao các lựa chọn khác sai:</strong> Ba trường hợp còn lại đều có người dùng đang nhìn màn hình, nơi hiện chữ sớm cải thiện trải nghiệm rõ rệt."},
  {"level": 1, "q": "Theo mặc định, route handler Next.js trả về <code>Response</code> có body là gì thì trình duyệt nhận được dữ liệu từng phần?", "options": ["Một chuỗi đã nối đủ toàn bộ câu trả lời", "Một object JSON trả qua <code>NextResponse.json()</code>", "Một <code>ReadableStream</code> được ghi dần bằng <code>controller.enqueue()</code>", "Một Promise trả về chuỗi"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Web Streams cho phép gửi từng chunk ngay khi có dữ liệu; route handler trả <code>new Response(readableStream)</code>.<br><strong>Vì sao các lựa chọn khác sai:</strong> Chuỗi đầy đủ hay <code>NextResponse.json()</code> chỉ gửi khi đã có toàn bộ nội dung; Promise trả chuỗi cũng chờ xong mới gửi."},
  {"level": 1, "q": "Script Node.js stream câu trả lời ra terminal. Hàm nào in từng đoạn chữ nối tiếp trên cùng dòng?", "options": ["<code>console.log(text)</code>", "<code>console.table(text)</code>", "<code>process.stdout.write(text)</code>", "<code>alert(text)</code>"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> <code>process.stdout.write</code> ghi đúng chuỗi nhận được, không thêm ký tự xuống dòng.<br><strong>Vì sao các lựa chọn khác sai:</strong> <code>console.log</code> thêm xuống dòng sau mỗi đoạn nên chữ bị vỡ thành nhiều dòng; <code>console.table</code> dùng để in bảng; <code>alert</code> chỉ có trên trình duyệt."},
  {"level": 2, "q": "Đoạn code NestJS sau có vấn đề gì?<pre><code>const message = await this.anthropic.messages.create({\n  model: \"claude-opus-5\", max_tokens: 16000, thinking: { type: \"adaptive\" }, messages: history,\n});\nhistory.push({ role: \"assistant\", content: (message.content[0] as any).text });</code></pre>", "options": ["Không có vấn đề, đây là cách khuyến nghị", "Sai vì role phải là \"model\"", "Chỉ lấy text của block đầu: mất block thinking và có thể lấy nhầm vì block đầu thường không phải text", "Sai vì thinking chỉ dùng được khi stream"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Khi bật thinking, block đầu thường là <code>thinking</code>; ép kiểu <code>as any</code> che lỗi và làm mất trạng thái. Nên push nguyên <code>message.content</code>.<br><strong>Vì sao các lựa chọn khác sai:</strong> Đây không phải cách khuyến nghị; role đúng là <code>assistant</code>; thinking dùng được cả khi không stream."},
  {"level": 2, "q": "Đoạn code sau gây lỗi gì cho các lượt sau khi request thất bại?<pre><code>history.push({ role: \"user\", content: question });\ntry {\n  const m = await client.messages.create({ model: \"claude-opus-5\", max_tokens: 16000, messages: history });\n  history.push({ role: \"assistant\", content: m.content });\n} catch (e) {\n  this.logger.error(e);\n}</code></pre>", "options": ["Không có vấn đề vì SDK tự xoá lượt user khi lỗi", "Lỗi vì history phải khai báo bằng const", "Lỗi vì try/catch không bắt được lỗi của SDK", "Lượt user bị lỗi vẫn nằm trong history, lượt sau sẽ có hai lượt user liền nhau; nên chỉ ghi khi thành công hoặc pop khi lỗi"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Lịch sử không còn xen kẽ đúng như mong muốn và câu hỏi lỗi bị lặp ngữ cảnh. Cách an toàn là ghi cặp user/assistant sau khi gọi thành công.<br><strong>Vì sao các lựa chọn khác sai:</strong> SDK không sửa mảng history của bạn; const hay let không liên quan (push vẫn được); lỗi SDK là exception thông thường nên try/catch bắt được."},
  {"level": 2, "q": "Route handler Next.js dưới đây thiếu gì khi người dùng đóng tab giữa chừng?<pre><code>export async function POST(req: Request) {\n  const { messages } = await req.json();\n  const stream = client.messages.stream({ model: \"claude-opus-5\", max_tokens: 64000, messages });\n  const body = new ReadableStream({\n    start(controller) {\n      stream.on(\"text\", (t) =&gt; controller.enqueue(encoder.encode(t)));\n      stream.on(\"end\", () =&gt; controller.close());\n      stream.on(\"error\", (e) =&gt; controller.error(e));\n    },\n  });\n  return new Response(body, { headers: { \"Content-Type\": \"text/plain; charset=utf-8\" } });\n}</code></pre>", "options": ["Không huỷ request tới Claude: cần thêm <code>cancel() { stream.abort(); }</code> trong ReadableStream (hoặc nghe <code>req.signal</code>)", "Thiếu <code>await stream.finalMessage()</code> trước khi return", "Thiếu header <code>Content-Length</code>", "Phải đổi sang <code>NextResponse.json()</code>"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Khi client ngắt, ReadableStream bị cancel nhưng stream tới Claude vẫn chạy và sinh token bị tính tiền. Gọi <code>stream.abort()</code> để dừng.<br><strong>Vì sao các lựa chọn khác sai:</strong> Await finalMessage trước khi return làm mất tác dụng streaming; response streaming không có Content-Length cố định; <code>NextResponse.json()</code> chỉ trả một lần."},
  {"level": 2, "q": "Trong endpoint NestJS sau, hàm trả về từ <code>new Observable</code> có tác dụng gì?<pre><code>@Sse(\"chat/stream\")\nstream(@Query(\"conversationId\") id: string): Observable&lt;MessageEvent&gt; {\n  return new Observable((sub) =&gt; {\n    const s = this.chat.openStream(id);\n    s.on(\"text\", (t) =&gt; sub.next({ data: { text: t } } as MessageEvent));\n    s.on(\"end\", () =&gt; sub.complete());\n    s.on(\"error\", (e) =&gt; sub.error(e));\n    return () =&gt; s.abort();\n  });\n}</code></pre>", "options": ["Khởi động lại stream khi có lỗi", "Gửi sự kiện cuối cùng cho client", "Không có tác dụng, NestJS bỏ qua giá trị trả về này", "Là teardown: khi client ngắt kết nối và Observable bị huỷ, nó dừng request tới Claude"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Hàm trả về từ subscriber function được RxJS gọi khi unsubscribe; NestJS unsubscribe khi kết nối SSE đóng.<br><strong>Vì sao các lựa chọn khác sai:</strong> Teardown không retry hay phát sự kiện; RxJS luôn gọi teardown khi huỷ đăng ký nên nó có tác dụng thật."},
  {"level": 2, "q": "Endpoint <code>@Sse()</code> của NestJS (và <code>EventSource</code> của trình duyệt) dùng method GET. Thiết kế nào hợp lý để gửi lịch sử dài?", "options": ["Mã hoá toàn bộ lịch sử vào query string của GET", "Gửi lịch sử qua header <code>Cookie</code>", "POST lưu tin nhắn user vào DB và trả <code>conversationId</code>, sau đó GET SSE theo <code>conversationId</code> để stream câu trả lời", "Đổi <code>@Sse()</code> sang nhận body JSON"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Tách \"ghi lượt\" và \"đọc stream\" giúp request GET gọn, server tự nạp lịch sử từ DB.<br><strong>Vì sao các lựa chọn khác sai:</strong> Query string và cookie có giới hạn độ dài, dễ lộ trong log; <code>@Sse()</code> gắn với GET nên không nhận body theo cách thông thường."},
  {"level": 2, "q": "Chạy đoạn Python sau, chữ hiển thị thế nào và sửa ra sao?<pre><code>with client.messages.stream(model=\"claude-opus-5\", max_tokens=64000, messages=history) as s:\n    for text in s.text_stream:\n        print(text)</code></pre>", "options": ["In đúng, không cần sửa", "Chỉ in đoạn cuối; phải gọi get_final_message() trước", "Mỗi đoạn in trên một dòng riêng; sửa thành <code>print(text, end=\"\", flush=True)</code>", "Lỗi vì text_stream chỉ dùng được với async"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> <code>print</code> mặc định thêm xuống dòng và có thể buffer; <code>end=\"\"</code> và <code>flush=True</code> cho chữ chảy liền mạch.<br><strong>Vì sao các lựa chọn khác sai:</strong> Output bị vỡ dòng nên không \"đúng\"; vòng lặp in mọi đoạn chứ không chỉ đoạn cuối; <code>text_stream</code> dùng được với client đồng bộ."},
  {"level": 2, "q": "Nhận định nào đúng về đoạn code TypeScript sau?<pre><code>const stream = client.messages.stream({ model: \"claude-opus-5\", max_tokens: 64000, messages: history })\n  .on(\"text\", (t) =&gt; process.stdout.write(t));\nconst final = await stream.finalMessage();\nhistory.push({ role: \"assistant\", content: final.content });</code></pre>", "options": ["<code>finalMessage()</code> chỉ trả phần text cuối cùng", "Phải bọc sự kiện \"end\" trong <code>new Promise</code> mới lấy được kết quả", "<code>finalMessage()</code> chờ stream kết thúc rồi trả Message đầy đủ (content, stop_reason, usage) để nối vào lịch sử", "Gọi <code>finalMessage()</code> gửi thêm một request nữa"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Đây là cách khuyến nghị: vừa in từng đoạn qua sự kiện \"text\", vừa có message hoàn chỉnh để lưu.<br><strong>Vì sao các lựa chọn khác sai:</strong> <code>finalMessage()</code> trả toàn bộ Message; tự bọc Promise là viết lại thứ SDK đã có; helper không gửi thêm request."},
  {"level": 2, "q": "Vì sao schema Prisma này lưu <code>content</code> dạng Json và có index như dưới?<pre><code>model Message {\n  id             String       @id @default(cuid())\n  conversationId String\n  role           String\n  content        Json\n  createdAt      DateTime     @default(now())\n  conversation   Conversation @relation(fields: [conversationId], references: [id])\n  @@index([conversationId, createdAt])\n}</code></pre>", "options": ["Json để Prisma tự nén token; index để API cache tốt hơn", "Json bắt buộc với mọi cột trong PostgreSQL; index để chống trùng", "Json giữ nguyên mảng content block để gửi lại API; index giúp nạp lịch sử một hội thoại theo đúng thứ tự thời gian nhanh", "Json để lưu API key; index để mã hoá dữ liệu"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Query điển hình là <code>where conversationId orderBy createdAt</code>, đúng với index kép này.<br><strong>Vì sao các lựa chọn khác sai:</strong> Prisma không nén token và index DB không ảnh hưởng prompt cache của API; Json không bắt buộc cho mọi cột; @@index không đảm bảo duy nhất; không lưu API key trong bảng message."},
  {"level": 2, "q": "Code nạp lịch sử sau có lỗi gì?<pre><code>const rows = await prisma.message.findMany({\n  where: { conversationId },\n  orderBy: { createdAt: \"desc\" },\n  take: 20,\n});\nconst messages = rows.map((r) =&gt; ({ role: r.role, content: r.content }));</code></pre>", "options": ["Không có lỗi", "Lỗi vì <code>take</code> không dùng chung được với <code>orderBy</code>", "Lỗi vì content Json không gửi được cho API", "Lịch sử bị đảo ngược thứ tự (mới nhất lên đầu) và có thể bắt đầu bằng lượt assistant; cần đảo lại và đảm bảo bắt đầu bằng user"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Lấy 20 bản ghi mới nhất là hợp lý, nhưng phải <code>reverse()</code> trước khi gửi và cắt sao cho lượt đầu là user.<br><strong>Vì sao các lựa chọn khác sai:</strong> Code chạy được nhưng sai ngữ nghĩa; Prisma hỗ trợ <code>take</code> cùng <code>orderBy</code>; content Json là object thuần gửi được cho API."},
  {"level": 2, "q": "Hàm rút gọn lịch sử sau có lỗi gì?<pre><code>function shrink(history: MessageParam[], summary: string): MessageParam[] {\n  return [\n    { role: \"user\", content: `Tóm tắt phần trước: ${summary}` },\n    ...history.slice(10), // history[10] là lượt user\n  ];\n}</code></pre>", "options": ["Không có lỗi", "Phải cắt <code>slice(9)</code> để bắt đầu bằng assistant", "Lượt tóm tắt (user) đứng ngay trước history[10] (cũng là user) nên có hai lượt user liền nhau; cần thêm một lượt assistant xác nhận hoặc gộp vào lượt user kế tiếp", "Tóm tắt phải đặt role system trong messages"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Các lượt cần xen kẽ user → assistant; thêm lượt assistant ngắn \"Đã hiểu\" là cách đơn giản giữ đúng cấu trúc.<br><strong>Vì sao các lựa chọn khác sai:</strong> Code chạy nhưng tạo lịch sử sai cấu trúc; slice(9) làm lượt đầu phần còn lại là assistant, ghép với tóm tắt thì vẫn lệch ý; đưa tóm tắt vào top-level system là một lựa chọn, nhưng không phải bằng cách thay role trong mảng này."},
  {"level": 2, "q": "Thứ tự sự kiện SSE nào đúng cho một message chỉ có một block text?", "options": ["<code>message_start</code> → <code>content_block_start</code> → nhiều <code>content_block_delta</code> → <code>content_block_stop</code> → <code>message_delta</code> → <code>message_stop</code>", "<code>content_block_start</code> → <code>message_start</code> → <code>content_block_delta</code> → <code>message_stop</code>", "<code>message_start</code> → <code>message_delta</code> → <code>content_block_delta</code> → <code>message_stop</code>", "<code>message_start</code> → <code>content_block_delta</code> → <code>message_stop</code> → <code>content_block_stop</code>"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Message mở đầu, rồi từng block được mở–delta–đóng, cuối cùng là message_delta (stop_reason, usage) và message_stop.<br><strong>Vì sao các lựa chọn khác sai:</strong> Các thứ tự khác đặt block trước message, đặt message_delta trước block, hoặc đóng block sau khi message đã dừng – không đúng giao thức."},
  {"level": 2, "q": "Trong vòng lặp sau, điều kiện nào in đúng phần text?<pre><code>for await (const event of stream) {\n  if (/* ? */) process.stdout.write(event.delta.text);\n}</code></pre>", "options": ["<code>event.type === \"content_block_delta\" &amp;&amp; event.delta.type === \"text_delta\"</code>", "<code>event.type === \"text\"</code>", "<code>event.type === \"message_delta\"</code>", "<code>event.delta !== undefined</code>"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Text đến trong content_block_delta kiểu text_delta; kiểm tra cả hai giúp TypeScript narrow kiểu để truy cập <code>delta.text</code>.<br><strong>Vì sao các lựa chọn khác sai:</strong> Sự kiện raw không có type \"text\" (đó là sự kiện helper của <code>.on()</code>); message_delta không mang text; chỉ kiểm tra delta tồn tại sẽ bắt cả thinking_delta, input_json_delta."},
  {"level": 2, "q": "Worker gọi <code>client.messages.create({ model: \"claude-opus-5\", max_tokens: 64000, ... })</code> không stream và SDK báo lỗi yêu cầu dùng streaming. Cách sửa ít thay đổi nhất?", "options": ["Tăng timeout HTTP của SDK lên 1 giờ và giữ nguyên", "Đổi sang <code>client.messages.stream({...})</code> rồi <code>await stream.finalMessage()</code>", "Giảm max_tokens xuống 256", "Gọi create hai lần và nối kết quả"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Không cần xử lý từng sự kiện: <code>finalMessage()</code> trả đúng kiểu Message như create, còn kết nối stream tránh timeout.<br><strong>Vì sao các lựa chọn khác sai:</strong> Tăng timeout vẫn để kết nối im lặng lâu, dễ bị proxy cắt; max_tokens 256 làm cắt cụt output; gọi hai lần không nối được một câu trả lời liền mạch và tốn gấp đôi."},
  {"level": 2, "q": "Trong component Next.js đọc stream, vì sao cần <code>{ stream: true }</code>?<pre><code>const reader = res.body!.getReader();\nconst decoder = new TextDecoder();\nwhile (true) {\n  const { done, value } = await reader.read();\n  if (done) break;\n  setText((t) =&gt; t + decoder.decode(value, { stream: true }));\n}</code></pre>", "options": ["Để TextDecoder nén dữ liệu", "Để bật chế độ SSE của fetch", "Ký tự UTF-8 nhiều byte (chữ tiếng Việt có dấu) có thể bị tách giữa hai chunk; stream: true giữ phần byte dở cho lần decode sau", "Không cần, chỉ để code dễ đọc"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Không có cờ này, byte dở dang bị decode thành ký tự lỗi (�) ở ranh giới chunk.<br><strong>Vì sao các lựa chọn khác sai:</strong> TextDecoder không nén; cờ này không liên quan tới SSE; bỏ cờ gây lỗi hiển thị thật với tiếng Việt."},
  {"level": 2, "q": "Local stream mượt, nhưng sau khi deploy sau reverse proxy nginx thì chữ hiện ra một cục ở cuối. Nguyên nhân khả dĩ nhất?", "options": ["Claude API tắt streaming trên production", "Next.js tự chuyển streaming thành JSON khi build", "Trình duyệt không hỗ trợ ReadableStream", "Proxy buffering gom response lại; tắt buffering (ví dụ header <code>X-Accel-Buffering: no</code> hoặc cấu hình proxy_buffering off)"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Nginx mặc định buffer response từ upstream; với streaming phải tắt để chunk đi thẳng tới client.<br><strong>Vì sao các lựa chọn khác sai:</strong> API không phân biệt môi trường; Next.js không đổi kiểu response khi build; trình duyệt hiện đại đều hỗ trợ ReadableStream và local vẫn chạy được."},
  {"level": 2, "q": "Mỗi cặp user/assistant thêm khoảng 1.000 token. Không dùng caching, request ở lượt thứ 20 có input khoảng bao nhiêu (bỏ qua system)?", "options": ["Khoảng 19.000–20.000 token vì gửi lại 19 cặp trước cộng câu hỏi mới", "Khoảng 1.000 token vì chỉ tính lượt mới", "Khoảng 500 token vì API tự nén lịch sử", "Khoảng 200.000 token vì mỗi lượt nhân đôi"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> API stateless nên input tăng tuyến tính theo số lượt; tổng chi phí cả hội thoại tăng theo bậc hai.<br><strong>Vì sao các lựa chọn khác sai:</strong> API không chỉ tính lượt mới vì bạn gửi lại toàn bộ; API không tự nén; input không nhân đôi mỗi lượt."},
  {"level": 2, "q": "System prompt sau làm prompt caching gần như không bao giờ hit. Vì sao?<pre><code>system: [{\n  type: \"text\",\n  text: `Bạn là trợ lý bán hàng. Thời điểm hiện tại: ${new Date().toISOString()}\\n${POLICY}`,\n  cache_control: { type: \"ephemeral\" },\n}]</code></pre>", "options": ["cache_control phải đặt ở lượt user đầu tiên mới có tác dụng", "Timestamp thay đổi mỗi request nên tiền tố khác nhau; đưa thông tin động xuống lượt user cuối hoặc làm tròn theo ngày", "Caching chỉ hoạt động khi không stream", "POLICY quá dài nên không cache được"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Cache so khớp từng byte của tiền tố; chuỗi ISO có mili-giây làm system prompt khác nhau ở mỗi lần gọi.<br><strong>Vì sao các lựa chọn khác sai:</strong> cache_control đặt trên system là hợp lệ; caching hoạt động cả khi stream; nội dung dài chính là thứ nên cache."},
  {"level": 2, "q": "Vì sao TypeScript bắt kiểm tra <code>b.type</code> trước khi đọc <code>b.text</code>?<pre><code>let out = \"\";\nfor (const b of message.content) {\n  if (b.type === \"text\") out += b.text;\n}</code></pre>", "options": ["Vì <code>text</code> là thuộc tính private", "Vì SDK chỉ trả text khi stream", "Không cần, chỉ để code dài hơn", "<code>content</code> là union nhiều loại block; kiểm tra <code>type</code> giúp narrow về TextBlock mới có thuộc tính <code>text</code>"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> ContentBlock là discriminated union (text, thinking, tool_use…); chỉ TextBlock có <code>text</code>.<br><strong>Vì sao các lựa chọn khác sai:</strong> Thuộc tính không private; response không stream vẫn có text; bỏ kiểm tra sẽ lỗi biên dịch và có thể đọc nhầm block khác."},
  {"level": 2, "q": "Dùng <code>claude-opus-5</code> với <code>thinking: { type: \"adaptive\" }</code> và không đặt <code>display</code>. Khi stream, phần thinking trông thế nào?", "options": ["Vẫn có block thinking nhưng nội dung để trống; muốn thấy bản tóm tắt suy nghĩ phải đặt <code>display: \"summarized\"</code>", "Thinking in đầy đủ từng token suy nghĩ", "Request lỗi 400 vì thiếu display", "Không có block thinking nào trong content"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Trên Claude Opus 5, mặc định display là omitted: block thinking tồn tại nhưng không có text suy nghĩ.<br><strong>Vì sao các lựa chọn khác sai:</strong> Không trả toàn bộ suy nghĩ thô; thiếu display không gây lỗi; block thinking vẫn xuất hiện và cần giữ khi nối lịch sử."},
  {"level": 2, "q": "Cách đúng để bắt lỗi API (ví dụ 529 overloaded) khi dùng stream trong service NestJS?<pre><code>const stream = this.anthropic.messages.stream({ ... });\ntry {\n  const final = await stream.finalMessage();\n} catch (err) {\n  // ?\n}</code></pre>", "options": ["Kiểm tra <code>err instanceof Anthropic.APIError</code> và đọc <code>err.status</code> để xử lý", "Kiểm tra <code>err.message.includes(\"overloaded\")</code>", "Không cần try/catch vì stream không bao giờ lỗi", "Đặt <code>max_tokens: 0</code> để tránh lỗi"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> <code>finalMessage()</code> reject khi stream lỗi; SDK dùng lớp lỗi có kiểu với trường <code>status</code>.<br><strong>Vì sao các lựa chọn khác sai:</strong> So khớp chuỗi message dễ vỡ khi thông điệp thay đổi; stream hoàn toàn có thể lỗi; max_tokens 0 không hợp lệ."},
  {"level": 2, "q": "Workflow sau chạy test tích hợp gọi Claude thật. PR mở từ fork luôn fail vì thiếu API key. Giải thích đúng?<pre><code>on: pull_request\njobs:\n  integration:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - run: pnpm install --frozen-lockfile\n      - run: pnpm --filter api test:integration\n        env:\n          ANTHROPIC_API_KEY: ${{ secrets.ANTHROPIC_API_KEY }}</code></pre>", "options": ["Phải đổi sang <code>pull_request_target</code> và checkout code của fork để có secret", "GitHub không truyền secrets vào workflow <code>pull_request</code> từ fork; dùng mock/fixture cho PR và chạy test gọi API thật ở nhánh chính hoặc theo lịch", "Secret phải viết hoa toàn bộ tên job", "Cần đặt API key thẳng trong file YAML"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Đây là cơ chế bảo mật của GitHub Actions: code từ fork không được đọc secret của repo.<br><strong>Vì sao các lựa chọn khác sai:</strong> Dùng <code>pull_request_target</code> rồi chạy code của fork với secret là lỗ hổng bảo mật kinh điển; tên job không liên quan; commit key vào YAML làm lộ key."},
  {"level": 2, "q": "Lượt tiếp theo sau một tool_use được viết như sau. Lỗi ở đâu?<pre><code>history.push({ role: \"assistant\", content: msg.content }); // có block tool_use id \"toolu_01\"\nhistory.push({ role: \"user\", content: `Kết quả tra đơn: ${JSON.stringify(order)}` });</code></pre>", "options": ["Phải đổi role thành \"tool\"", "Lượt user phải chứa block <code>{ type: \"tool_result\", tool_use_id: \"toolu_01\", content: ... }</code> chứ không phải chuỗi text", "Kết quả tool phải đặt trong system prompt", "Không có lỗi, API tự hiểu"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> API yêu cầu mỗi tool_use được trả lời bằng tool_result có <code>tool_use_id</code> khớp ở lượt user ngay sau.<br><strong>Vì sao các lựa chọn khác sai:</strong> Messages API không có role \"tool\"; system prompt không dùng để trả kết quả tool; chuỗi text không liên kết với lời gọi tool nên request bị từ chối."},
  {"level": 2, "q": "Hàm sau dùng <code>countTokens</code> để làm gì hợp lý nhất?<pre><code>const { input_tokens } = await client.messages.countTokens({\n  model: \"claude-opus-5\", system: SYSTEM, messages: history,\n});\nif (input_tokens &gt; 150_000) history = await summarizeOld(history);</code></pre>", "options": ["Đếm trước token input để quyết định tóm tắt lịch sử trước khi gửi request thật", "Tính số token output Claude sẽ sinh", "Kiểm tra API key còn hạn", "Bật prompt caching cho history"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Token counting cho biết kích thước input của request, giúp chủ động cắt/tóm tắt thay vì chờ lỗi quá dài.<br><strong>Vì sao các lựa chọn khác sai:</strong> Output chưa sinh nên không đếm trước được; count_tokens không kiểm tra hạn key; nó không bật caching."},
  {"level": 2, "q": "Vì sao route handler sau bọc mỗi đoạn text bằng <code>JSON.stringify</code> trước khi gửi SSE?<pre><code>stream.on(\"text\", (t) =&gt; {\n  controller.enqueue(encoder.encode(`data: ${JSON.stringify({ text: t })}\\n\\n`));\n});</code></pre>", "options": ["Để giảm số token bị tính", "Text có thể chứa ký tự xuống dòng; SSE dùng dòng trống để tách sự kiện nên phải mã hoá để không vỡ khung", "Vì SSE chỉ cho phép ASCII", "Để Claude hiểu định dạng output"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Mỗi sự kiện SSE là các dòng <code>data:</code> kết thúc bằng dòng trống; một <code>\\n\\n</code> trong text sẽ cắt sự kiện sai chỗ.<br><strong>Vì sao các lựa chọn khác sai:</strong> Token đã được tính ở phía API; SSE dùng UTF-8 chứ không chỉ ASCII; bước này xảy ra sau khi Claude sinh xong đoạn text."},
  {"level": 2, "q": "Frontend muốn gọi <code>POST /api/chat</code> với body JSON và đọc stream. Vì sao không dùng được <code>new EventSource()</code>?", "options": ["<code>EventSource</code> không hỗ trợ UTF-8", "<code>EventSource</code> chỉ gửi GET và không cho đặt body; dùng <code>fetch</code> rồi đọc <code>res.body.getReader()</code>", "<code>EventSource</code> chỉ chạy trong Web Worker", "<code>EventSource</code> bị Next.js chặn"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> EventSource là API GET-only; với POST, cách thông dụng là fetch và tự parse luồng.<br><strong>Vì sao các lựa chọn khác sai:</strong> EventSource hỗ trợ UTF-8, chạy trên main thread bình thường và Next.js không chặn nó."},
  {"level": 2, "q": "Đoạn code sau quên gì khiến lượt kế tiếp Claude không thấy câu hỏi vừa rồi?<pre><code>const final = await client.messages\n  .stream({ model: \"claude-opus-5\", max_tokens: 64000, messages: [...history, { role: \"user\", content: q }] })\n  .finalMessage();\nhistory.push({ role: \"assistant\", content: final.content });</code></pre>", "options": ["Không push lượt user <code>q</code> vào history, nên lịch sử lưu lại thiếu câu hỏi và mất xen kẽ", "Quên gọi <code>stream.abort()</code>", "Quên đặt <code>stop_sequences</code>", "Không quên gì, code đúng"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Spread tạo mảng tạm cho request, còn <code>history</code> gốc chỉ nhận lượt assistant; lượt sau sẽ có hai assistant liền nhau.<br><strong>Vì sao các lựa chọn khác sai:</strong> abort chỉ dùng để huỷ; stop_sequences không liên quan tới lịch sử; code có lỗi logic thật."},
  {"level": 2, "q": "Người dùng huỷ stream giữa chừng sau khi Claude đã sinh 800 token. Nhận định nào đúng về chi phí?", "options": ["Không bị tính gì vì request chưa hoàn tất", "Bị tính đủ max_tokens", "Chỉ bị tính khi stop_reason là end_turn", "Vẫn bị tính cho input và phần output đã sinh trước khi huỷ"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Token đã xử lý và đã sinh đều có chi phí; huỷ sớm chỉ ngăn phát sinh thêm.<br><strong>Vì sao các lựa chọn khác sai:</strong> Request dở dang vẫn tiêu tài nguyên; phí không tính theo max_tokens mà theo token thực tế; stop_reason không quyết định việc tính tiền."},
  {"level": 2, "q": "Trợ lý hỗ trợ có nhiều <code>tool_result</code> cũ rất lớn (log, nội dung file) làm lịch sử phình to. Kỹ thuật nào nhắm đúng phần này?", "options": ["Tăng max_tokens", "Context editing: xoá bớt kết quả tool cũ không còn cần thiết khỏi ngữ cảnh", "Chuyển sang model có context nhỏ hơn", "Tắt streaming"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Context editing được thiết kế để dọn các kết quả tool cũ; compaction/tóm tắt xử lý phần hội thoại nói chung (chi tiết ở tháng 5).<br><strong>Vì sao các lựa chọn khác sai:</strong> max_tokens chỉ giới hạn output; context nhỏ hơn làm vấn đề tệ hơn; streaming không đổi kích thước input."},
  {"level": 2, "q": "Stream dừng với <code>stop_reason: \"max_tokens\"</code> khi đang viết dở báo cáo. Cách xử lý phù hợp trên model mới?", "options": ["Prefill lượt assistant cuối bằng đoạn dở rồi gọi lại", "Bỏ qua, coi như đã xong", "Báo cho người dùng, tăng <code>max_tokens</code> hoặc gửi lượt user \"Hãy viết tiếp phần còn lại\" sau khi nối lượt assistant dở", "Chuyển sang temperature 2"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Nối nguyên phần đã sinh làm lượt assistant, rồi thêm lượt user yêu cầu viết tiếp giữ đúng cấu trúc xen kẽ.<br><strong>Vì sao các lựa chọn khác sai:</strong> Prefill lượt assistant cuối không được hỗ trợ trên các model mới (trả 400); coi như xong làm mất nội dung; temperature không giải quyết việc bị cắt."},
  {"level": 2, "q": "Trong Python, vì sao <code>json.dump(history, f)</code> lỗi \"not JSON serializable\" sau khi nối <code>final.content</code>?", "options": ["Content block trong SDK Python là object Pydantic; cần <code>[b.model_dump() for b in final.content]</code> trước khi lưu", "Vì history chứa ký tự tiếng Việt", "Vì phải dùng pickle cho mọi dữ liệu API", "Vì final.content là chuỗi bytes"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> SDK Python trả model Pydantic; <code>model_dump()</code> chuyển về dict thuần.<br><strong>Vì sao các lựa chọn khác sai:</strong> Tiếng Việt chỉ cần <code>ensure_ascii=False</code> để dễ đọc, không gây lỗi; pickle không cần thiết và kém an toàn; content không phải bytes."},
  {"level": 2, "q": "Bật automatic caching như dưới trong chatbot nhiều lượt. Kết quả mong đợi?<pre><code>const res = await client.messages.create({\n  model: \"claude-opus-5\", max_tokens: 16000,\n  cache_control: { type: \"ephemeral\" },\n  system: SYSTEM,\n  messages: history,\n});\nconsole.log(res.usage.cache_read_input_tokens);</code></pre>", "options": ["Chỉ system prompt được cache, messages không bao giờ", "Output được cache nên câu trả lời giống nhau mỗi lần", "Không có tác dụng khi dùng system prompt", "Từ lượt thứ hai, phần tiền tố giống lượt trước được đọc từ cache nên <code>cache_read_input_tokens</code> tăng dần"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Automatic caching đánh dấu block cacheable cuối cùng; với lịch sử append-only, tiền tố lượt trước khớp cache ở lượt sau.<br><strong>Vì sao các lựa chọn khác sai:</strong> Messages cũng được cache; caching chỉ áp dụng cho input chứ không lưu output; system prompt không cản caching."},
  {"level": 2, "q": "Service NestJS sau lưu lịch sử trong một <code>Map</code> trên bộ nhớ process và chạy 4 task ECS sau ALB. Vấn đề là gì?<pre><code>@Injectable()\nexport class ChatService {\n  private histories = new Map&lt;string, MessageParam[]&gt;();\n  async reply(conversationId: string, q: string) { /* đọc/ghi this.histories */ }\n}</code></pre>", "options": ["Mỗi task có Map riêng; request lần sau có thể rơi vào task khác nên mất lịch sử, và mất hết khi task restart", "Map không lưu được object", "NestJS không cho dùng Map trong provider", "ALB tự đồng bộ bộ nhớ giữa các task"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> State hội thoại cần nằm ngoài process (PostgreSQL/Redis) khi chạy nhiều instance.<br><strong>Vì sao các lựa chọn khác sai:</strong> Map lưu object bình thường; NestJS không cấm; ALB chỉ phân phối request, không đồng bộ bộ nhớ."},
  {"level": 2, "q": "Nên hiển thị lời chào \"Xin chào, tôi có thể giúp gì?\" trên UI chatbot thế nào cho hợp lý?", "options": ["Gọi API mỗi lần mở trang để Claude tự chào", "Prefill lượt assistant cuối bằng lời chào", "Hiển thị trên UI như tin nhắn tĩnh; không cần gọi API để sinh lời chào, lịch sử gửi lên bắt đầu từ câu hỏi đầu tiên của user", "Đặt lời chào vào <code>max_tokens</code>"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Lời chào cố định không cần model sinh; bỏ nó khỏi lịch sử giúp cấu trúc bắt đầu bằng user gọn gàng và tiết kiệm token.<br><strong>Vì sao các lựa chọn khác sai:</strong> Gọi API chỉ để chào tốn chi phí và độ trễ; prefill lượt cuối không được hỗ trợ trên model mới; max_tokens là số nguyên giới hạn output."},
  {"level": 2, "q": "Next.js route handler proxy stream từ NestJS. Tại sao nên chuyển tiếp <code>req.signal</code> vào fetch upstream?<pre><code>export async function POST(req: Request) {\n  const upstream = await fetch(`${process.env.API_URL}/chat/stream`, {\n    method: \"POST\", body: await req.text(), signal: req.signal,\n    headers: { \"Content-Type\": \"application/json\" },\n  });\n  return new Response(upstream.body, { headers: { \"Content-Type\": \"text/event-stream\" } });\n}</code></pre>", "options": ["Để fetch nhanh hơn", "Khi trình duyệt ngắt, request tới NestJS cũng bị huỷ, để NestJS dừng stream tới Claude và không tốn token", "Để truyền API key xuống NestJS", "Bắt buộc, nếu thiếu thì fetch lỗi"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> AbortSignal lan truyền việc huỷ qua từng tầng: browser → Next.js → NestJS → Claude.<br><strong>Vì sao các lựa chọn khác sai:</strong> Signal không ảnh hưởng tốc độ; không mang theo credential; fetch vẫn chạy bình thường nếu thiếu signal."},
  {"level": 2, "q": "Thông tin dạng \"Khách 35 tuổi, quan tâm gói A\" bị mất sau khi tóm tắt lịch sử. Cải tiến hợp lý nhất?", "options": ["Không tóm tắt nữa, gửi lại toàn bộ 60 lượt mãi mãi", "Tăng max_tokens của câu trả lời chính", "Hướng dẫn prompt tóm tắt giữ lại dữ kiện quan trọng, hoặc tách các dữ kiện đó thành phần \"hồ sơ\" riêng luôn được gửi kèm", "Tóm tắt lại sau mỗi lượt"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Tóm tắt có chỉ dẫn và bộ dữ kiện có cấu trúc giữ được thông tin cốt lõi với chi phí thấp.<br><strong>Vì sao các lựa chọn khác sai:</strong> Gửi toàn bộ mãi mãi làm chi phí tăng không kiểm soát; max_tokens không liên quan tới input; tóm tắt mỗi lượt phá cache liên tục và dễ trôi thông tin."},
  {"level": 2, "q": "Theo mặc định, SDK TypeScript xử lý lỗi 429/5xx tạm thời thế nào?", "options": ["Không bao giờ retry", "Retry vô hạn tới khi thành công", "Tự retry với backoff một số lần (mặc định 2), có thể chỉnh bằng <code>maxRetries</code> khi tạo client", "Chuyển sang model khác"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> SDK có retry sẵn cho lỗi kết nối, 429 và lỗi server; cấu hình được qua <code>new Anthropic({ maxRetries })</code>.<br><strong>Vì sao các lựa chọn khác sai:</strong> SDK có retry; không retry vô hạn; SDK không tự đổi model."},
  {"level": 2, "q": "Trình duyệt dùng <code>EventSource</code> tự kết nối lại khi mạng chập chờn. Rủi ro với endpoint GET <code>/chat/stream?conversationId=..</code> gọi Claude mỗi khi có kết nối?", "options": ["Không rủi ro, API tự loại trùng", "EventSource không bao giờ reconnect", "Reconnect làm mất API key", "Mỗi lần reconnect sinh thêm một request Claude mới, tốn tiền và có thể tạo câu trả lời trùng"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Endpoint cần idempotent: gắn id cho lượt trả lời và cho phép đọc tiếp từ buffer thay vì gọi lại model.<br><strong>Vì sao các lựa chọn khác sai:</strong> Messages API không tự khử trùng; EventSource có cơ chế reconnect mặc định; reconnect không ảnh hưởng key phía server."},
  {"level": 2, "q": "Dữ liệu content block trả về từ SDK TypeScript có lưu thẳng vào cột <code>Json</code> của Prisma được không?", "options": ["Không, phải gọi <code>model_dump()</code> như Python", "Không, phải chuyển thành XML", "Chỉ lưu được text block", "Được, chúng là object JSON thuần; có thể cần ép kiểu sang <code>Prisma.InputJsonValue</code> cho TypeScript"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> SDK TS trả dữ liệu đã parse từ JSON, nên serialize lại được ngay.<br><strong>Vì sao các lựa chọn khác sai:</strong> <code>model_dump()</code> là của Pydantic trong Python; không cần XML; mọi loại block đều là JSON."},
  {"level": 2, "q": "Trong NestJS, endpoint không dùng <code>@Sse()</code> mà dùng <code>@Res()</code> để stream thủ công. Điều gì cần nhớ?<pre><code>@Post(\"chat\")\nasync chat(@Body() dto: ChatDto, @Res() res: Response) {\n  res.setHeader(\"Content-Type\", \"text/event-stream\");\n  const s = this.anthropic.messages.stream({ ... });\n  s.on(\"text\", (t) =&gt; res.write(`data: ${JSON.stringify({ t })}\\n\\n`));\n  await s.finalMessage();\n  res.end();\n}</code></pre>", "options": ["NestJS tự gọi res.end() và tự huỷ stream", "Không được set header khi dùng @Res()", "Khi dùng <code>@Res()</code>, bạn tự chịu trách nhiệm kết thúc response và nên nghe <code>res.on(\"close\")</code> để <code>s.abort()</code> khi client ngắt", "Phải return giá trị để NestJS serialize"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Inject <code>@Res()</code> đưa bạn sang chế độ tự quản lý response của Express; việc huỷ request Claude khi client đi cũng phải tự làm.<br><strong>Vì sao các lựa chọn khác sai:</strong> NestJS không can thiệp vào response khi bạn dùng @Res() (trừ passthrough); set header được; return giá trị bị bỏ qua ở chế độ này."},
  {"level": 2, "q": "Vì sao nên tách chuỗi sự kiện SSE (kiểu <code>{type: \"text\" | \"done\" | \"error\"}</code>) thành type dùng chung trong <code>packages/shared</code>?", "options": ["Để giảm token gửi cho Claude", "Vì Turborepo bắt buộc mọi type phải nằm trong packages", "Để trình duyệt tự parse SSE", "Để <code>apps/api</code> (NestJS) và <code>apps/web</code> (Next.js) dùng cùng một hợp đồng, đổi một chỗ thì TypeScript báo lỗi ở cả hai"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Contract dùng chung tránh việc backend đổi tên trường mà frontend không biết.<br><strong>Vì sao các lựa chọn khác sai:</strong> Type TypeScript không ảnh hưởng token; Turborepo không bắt buộc như vậy; trình duyệt không đọc type TS."},
  {"level": 3, "q": "Chatbot NestJS chạy trên ECS Fargate sau ALB (idle timeout mặc định 60 giây). Với câu hỏi khó, <code>claude-opus-5</code> suy nghĩ lâu trước khi có chữ đầu tiên; server chỉ chuyển tiếp sự kiện \"text\" nên kết nối tới trình duyệt thỉnh thoảng bị ALB cắt. Cách xử lý tốt nhất?", "options": ["Tắt thinking cho mọi câu hỏi", "Gửi heartbeat SSE (dòng comment <code>: ping</code>) định kỳ trong lúc chờ và/hoặc tăng idle timeout của ALB cho phù hợp", "Chuyển sang gọi không stream để ALB chờ", "Chuyển toàn bộ sang API Gateway REST để có timeout dài hơn"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Kết nối bị cắt vì im lặng quá idle timeout; heartbeat giữ kết nối có dữ liệu mà không đổi chất lượng câu trả lời.<br><strong>Vì sao các lựa chọn khác sai:</strong> Tắt thinking làm giảm chất lượng với câu hỏi khó; không stream thì kết nối càng im lặng lâu hơn; API Gateway REST có timeout tích hợp mặc định 29 giây, còn ngắn hơn."},
  {"level": 3, "q": "Frontend Next.js gửi toàn bộ <code>messages</code> (kể cả lượt assistant) lên server mỗi lượt, server chuyển thẳng cho Claude. Đội bảo mật lo ngại gì nhất?", "options": ["Lộ API key vì messages chứa key", "Tốn băng thông nên cần gzip", "Next.js không cho gửi mảng lớn", "Client có thể giả mạo lượt assistant hoặc chèn nội dung để thao túng ngữ cảnh; nên lưu lịch sử phía server theo conversationId và kiểm tra quyền sở hữu"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Lịch sử là dữ liệu tin cậy của hệ thống; để client toàn quyền ghi là cho phép \"nói hộ\" Claude. Lưu phía server và gắn với user đã xác thực.<br><strong>Vì sao các lựa chọn khác sai:</strong> messages không chứa API key; băng thông là mối lo phụ; Next.js không có giới hạn như vậy."},
  {"level": 3, "q": "Hai tab cùng một hội thoại gửi tin gần như đồng thời. Code đọc JSON history từ Redis, thêm lượt, rồi <code>SET</code> lại. Hậu quả và cách sửa?", "options": ["Không sao vì Redis là single-thread", "Lost update: một tab ghi đè lượt của tab kia; lưu mỗi lượt thành một bản ghi (Prisma <code>create</code>) có thứ tự, hoặc khoá theo conversationId", "Redis tự merge hai mảng JSON", "Chỉ cần tăng TTL của key"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Read-modify-write không nguyên tử giữa hai request; Redis single-thread chỉ đảm bảo từng lệnh nguyên tử, không phải cả chuỗi đọc–sửa–ghi.<br><strong>Vì sao các lựa chọn khác sai:</strong> Redis không merge JSON thay bạn; TTL không liên quan tới xung đột ghi."},
  {"level": 3, "q": "Chatbot bảo hiểm có hội thoại trung bình 60 lượt, chi phí input tăng mạnh. Ràng buộc: giữ dữ kiện quan trọng, không tăng độ trễ lượt thường. Phương án nào cân bằng nhất?", "options": ["Giữ lịch sử append-only với prompt caching; khi vượt ngưỡng (ví dụ 20 lượt) mới tóm tắt phần cũ bằng Haiku ở nền", "Chỉ gửi 5 lượt gần nhất", "Tóm tắt lại sau mỗi lượt bằng Opus", "Tắt streaming để giảm token"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Caching giảm giá và độ trễ cho phần tiền tố lặp lại; tóm tắt thưa bằng model rẻ kiểm soát độ dài mà ít phá cache.<br><strong>Vì sao các lựa chọn khác sai:</strong> Cắt cứng 5 lượt làm mất dữ kiện; tóm tắt mỗi lượt vừa đắt vừa phá cache liên tục; streaming không đổi số token."},
  {"level": 3, "q": "Mục tiêu: giảm thời gian tới chữ đầu tiên cho chatbot có system prompt 8.000 token cố định. Kết hợp nào hiệu quả nhất?", "options": ["Tăng max_tokens", "Gọi không stream nhưng song song hai request", "Streaming cộng prompt caching cho system prompt cố định", "Chèn timestamp vào system prompt để luôn \"mới\""], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Streaming cho chữ hiện ngay khi sinh; cache read giúp xử lý tiền tố dài nhanh và rẻ hơn.<br><strong>Vì sao các lựa chọn khác sai:</strong> max_tokens không ảnh hưởng chữ đầu tiên; hai request song song gấp đôi chi phí mà không nhanh hơn; timestamp phá cache."},
  {"level": 3, "q": "Next.js gọi API Gateway REST → Lambda để sinh báo cáo 6.000 từ (mất khoảng 3 phút), người dùng hay gặp 504. Kiến trúc nào phù hợp?", "options": ["Tăng max_tokens và thử lại khi 504", "Đổi sang Haiku để kịp dưới 29 giây", "Gọi create không stream trong Lambda với timeout 15 phút sau API Gateway", "Trả <code>jobId</code> ngay, đẩy việc vào SQS; worker (Lambda/ECS) dùng <code>messages.stream()</code> + <code>finalMessage()</code>, lưu kết quả vào S3/DB, frontend poll hoặc nhận thông báo"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Tách request đồng bộ khỏi việc sinh dài giúp tránh timeout tích hợp của API Gateway; stream trong worker tránh timeout HTTP tới Claude.<br><strong>Vì sao các lựa chọn khác sai:</strong> Thử lại chỉ lặp lại lỗi và tốn tiền; đổi model hy sinh chất lượng mà vẫn không đảm bảo thời gian; Lambda có thể chạy 15 phút nhưng API Gateway phía trước vẫn cắt ở ngưỡng timeout của nó."},
  {"level": 3, "q": "Lambda xử lý SQS gọi Claude, timeout hàm là 5 phút. Một số job bị xử lý hai lần (sinh hai báo cáo). Nguyên nhân và cách sửa đúng?", "options": ["Claude API tự gửi lại kết quả hai lần", "Do bật streaming", "Do batch size bằng 1", "Visibility timeout của queue ngắn hơn thời gian xử lý nên message hiện lại; đặt visibility timeout lớn hơn nhiều so với timeout hàm (AWS khuyến nghị khoảng 6 lần) và làm xử lý idempotent"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Khi message chưa bị xoá trước khi hết visibility timeout, SQS giao lại cho consumer khác.<br><strong>Vì sao các lựa chọn khác sai:</strong> API không tự gửi trùng; streaming không liên quan tới SQS; batch size 1 không gây xử lý lặp."},
  {"level": 3, "q": "Để frontend gọi thẳng Claude cho \"nhanh\", team đặt <code>NEXT_PUBLIC_ANTHROPIC_API_KEY</code>. Đánh giá?", "options": ["Ổn nếu repo private", "Sai: biến <code>NEXT_PUBLIC_</code> bị nhúng vào bundle trình duyệt nên lộ key; gọi Claude từ route handler/NestJS, key lấy từ Secrets Manager inject vào task ECS", "Ổn nếu minify code", "Ổn nếu chỉ dùng cho streaming"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Mọi thứ gửi xuống trình duyệt đều đọc được; secret phải ở phía server.<br><strong>Vì sao các lựa chọn khác sai:</strong> Repo private không bảo vệ bundle đã phát hành; minify không che chuỗi; streaming không đổi tính chất lộ key."},
  {"level": 3, "q": "Công ty yêu cầu lưu lượng tới model đi qua tài khoản AWS và dùng Amazon Bedrock. Service NestJS cần giữ nguyên logic stream. Cấu hình nào đúng theo khoá học?<pre><code>import { AnthropicBedrockMantle } from \"@anthropic-ai/bedrock-sdk\";\nconst client = new AnthropicBedrockMantle({ awsRegion: \"us-east-1\" });\nconst stream = client.messages.stream({ model: MODEL, max_tokens: 64000, messages: history });</code></pre>", "options": ["<code>MODEL = \"claude-opus-5\"</code> và đặt ANTHROPIC_API_KEY trong env", "<code>MODEL = \"anthropic.claude-opus-5\"</code>, dùng credential IAM của task role thay vì ANTHROPIC_API_KEY", "<code>MODEL = \"bedrock/opus\"</code>", "Bedrock không hỗ trợ stream nên phải đổi sang create"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Trên Bedrock, model ID có tiền tố <code>anthropic.</code> và xác thực bằng AWS credentials (task role trên ECS).<br><strong>Vì sao các lựa chọn khác sai:</strong> API key Anthropic không dùng cho Bedrock; <code>bedrock/opus</code> không phải model ID hợp lệ; streaming vẫn dùng được qua client Bedrock (kiểm tra tài liệu mới nhất cho chi tiết)."},
  {"level": 3, "q": "Người dùng gửi tin mới trong lúc agent đang chờ kết quả tool (lượt assistant cuối có tool_use chưa có tool_result). Request tiếp theo bị 400. Cách xử lý đúng?<pre><code>[\n  { role: \"user\", content: \"Tra đơn #123\" },\n  { role: \"assistant\", content: [ { type: \"tool_use\", id: \"toolu_9\", name: \"get_order\", input: { id: \"123\" } } ] },\n  { role: \"user\", content: \"Thôi, cho tôi hỏi phí ship\" }\n]</code></pre>", "options": ["Xoá lượt user đầu tiên", "Đổi tool_use thành text", "Thêm một lượt assistant rỗng", "Lượt user phải bắt đầu bằng <code>tool_result</code> cho <code>toolu_9</code> (ví dụ <code>is_error: true</code>, \"người dùng đã huỷ\"), sau đó mới tới block text câu hỏi mới"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Mỗi tool_use cần một tool_result tương ứng ở lượt user ngay sau; có thể kèm text trong cùng lượt đó.<br><strong>Vì sao các lựa chọn khác sai:</strong> Xoá lượt user đầu làm mảng bắt đầu bằng assistant và vẫn thiếu tool_result; sửa tool_use thành text là giả mạo lịch sử; lượt assistant rỗng không hợp lệ và không giải quyết tool_use treo."},
  {"level": 3, "q": "Để tiết kiệm token, team xoá mọi block <code>thinking</code> khỏi lịch sử trước khi gửi lại, kể cả trong vòng lặp tool use đang chạy. Rủi ro chính?", "options": ["Không rủi ro gì, thinking chỉ để hiển thị", "Chi phí tăng vì phải sinh lại thinking bằng token input", "Streaming sẽ ngừng hoạt động", "Mất trạng thái suy luận gắn với lời gọi tool; trong vòng tool use, API yêu cầu hoặc cần block thinking nguyên vẹn nên có thể lỗi hoặc giảm chất lượng"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Lesson nhấn mạnh nối nguyên content; block thinking có chữ ký và gắn với tool_use cùng lượt.<br><strong>Vì sao các lựa chọn khác sai:</strong> Thinking không chỉ để hiển thị; xoá không làm tăng chi phí input; streaming không phụ thuộc vào việc này."},
  {"level": 3, "q": "Hàm \"làm sạch\" lịch sử chạy trước mỗi request: chuẩn hoá khoảng trắng và viết lại lượt cũ. <code>cache_read_input_tokens</code> luôn bằng 0. Kết luận?", "options": ["Caching bị tắt với tiếng Việt", "Phải dùng TTL 1h mới hit", "Streaming làm cache không hoạt động", "Việc viết lại lượt cũ làm tiền tố khác mỗi lần; chỉ chuẩn hoá lượt mới khi thêm vào rồi giữ nguyên (append-only)"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Cache so khớp chính xác tiền tố; đổi dù một khoảng trắng ở lượt cũ cũng làm mất cache.<br><strong>Vì sao các lựa chọn khác sai:</strong> Caching không phụ thuộc ngôn ngữ; TTL chỉ quyết định thời gian sống; streaming không ảnh hưởng caching."},
  {"level": 3, "q": "Monorepo Turborepo: đổi schema sự kiện stream trong <code>packages/shared</code>. CI chỉ muốn chạy test của những gì bị ảnh hưởng. Lệnh nào phù hợp?", "options": ["<code>pnpm --filter web test</code> chỉ chạy web", "<code>turbo run test --force</code> mọi lần", "<code>pnpm turbo run test --filter=...[origin/main]</code> để chạy package thay đổi và các package phụ thuộc vào nó", "Bỏ test vì chỉ đổi type"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Cú pháp <code>...[ref]</code> chọn package đổi so với ref cùng các dependents, nên cả apps/api và apps/web dùng shared đều được test.<br><strong>Vì sao các lựa chọn khác sai:</strong> Chỉ chạy web bỏ sót api; <code>--force</code> bỏ qua cache và chạy tất cả, lãng phí; đổi type là đổi hợp đồng nên cần test."},
  {"level": 3, "q": "Dashboard CloudWatch của chatbot cần chỉ số để phát hiện sớm \"caching hỏng\" và \"hội thoại quá dài\". Nên ghi gì từ <code>finalMessage().usage</code> mỗi lượt?", "options": ["<code>input_tokens</code>, <code>cache_read_input_tokens</code>, <code>cache_creation_input_tokens</code>, <code>output_tokens</code> theo conversationId", "Chỉ <code>output_tokens</code>", "Chỉ độ dài chuỗi text trả về", "Số lần gọi <code>on(\"text\")</code>"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Tỷ lệ cache read so với input cho biết caching có hoạt động; input_tokens tăng theo lượt cho thấy lịch sử phình to.<br><strong>Vì sao các lựa chọn khác sai:</strong> Chỉ output bỏ sót phần chi phí lớn nhất là input; độ dài chuỗi và số sự kiện text không phản ánh token hay cache."},
  {"level": 3, "q": "Người dùng bấm \"Dừng\" khi Claude đang trả lời. Frontend huỷ fetch, server gọi <code>stream.abort()</code>. Nên lưu gì vào lịch sử để lượt sau hợp lệ?", "options": ["Chỉ lưu lượt user, bỏ lượt assistant", "Lưu lượt assistant với content rỗng", "Không lưu gì nhưng giữ lượt user trong DB", "Lưu phần text đã nhận làm lượt assistant (đánh dấu bị dừng) hoặc bỏ cả cặp user/assistant đó, để lịch sử vẫn xen kẽ"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Cả hai cách đều giữ cấu trúc user → assistant; cách đầu còn cho Claude biết mình đã nói tới đâu.<br><strong>Vì sao các lựa chọn khác sai:</strong> Giữ lượt user mà không có assistant tạo hai lượt user liên tiếp; content rỗng không hợp lệ."},
  {"level": 3, "q": "Giờ cao điểm, API trả 429. Service NestJS đang tự viết vòng retry 10 lần không chờ. Phương án tốt nhất?", "options": ["Tăng lên 50 lần retry ngay lập tức", "Dựa vào retry có backoff sẵn của SDK (cấu hình <code>maxRetries</code>), tôn trọng <code>retry-after</code>, và giới hạn đồng thời/queue phía server", "Chuyển sang streaming để tránh rate limit", "Tạo thêm API key để lách giới hạn"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Backoff giảm tải khi bị giới hạn; giới hạn đồng thời ngăn tạo thêm áp lực.<br><strong>Vì sao các lựa chọn khác sai:</strong> Retry dồn dập làm tệ hơn; streaming không miễn rate limit; tạo key để lách không phải cách quản lý giới hạn đúng (giới hạn thường theo tổ chức)."},
  {"level": 3, "q": "Đề xuất nội bộ: \"Chuyển toàn bộ sang streaming để giảm 30% chi phí token\". Phản hồi đúng của reviewer?", "options": ["Streaming không đổi giá token; nó giảm độ trễ cảm nhận và tránh timeout. Muốn giảm chi phí hãy xem caching, Batches API cho việc không gấp, chọn model phù hợp", "Đồng ý, streaming rẻ hơn khoảng 30%", "Đồng ý nếu dùng thinking", "Chỉ rẻ hơn khi dùng tiếng Việt"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Đây là bẫy đề thi quen thuộc: streaming không phải kỹ thuật giảm giá.<br><strong>Vì sao các lựa chọn khác sai:</strong> Không có mức giảm giá nào cho streaming, bất kể thinking hay ngôn ngữ."},
  {"level": 3, "q": "Mỗi đêm cần tóm tắt 10.000 hội thoại cũ để làm báo cáo, không ai chờ kết quả ngay. Lựa chọn tối ưu chi phí?", "options": ["Stream từng hội thoại để nhanh hơn", "Message Batches API (giảm khoảng 50% giá), xử lý bất đồng bộ", "Gọi song song 10.000 request create cùng lúc", "Dùng Opus với effort max cho chắc"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Việc không cần phản hồi tức thì là trường hợp điển hình của Batches API.<br><strong>Vì sao các lựa chọn khác sai:</strong> Streaming không giảm giá và không cần thiết khi không ai xem; bắn 10.000 request cùng lúc dễ chạm rate limit; effort max tăng chi phí không cần thiết cho việc tóm tắt."},
  {"level": 3, "q": "Endpoint SSE của bạn bị reconnect (EventSource gửi <code>Last-Event-ID</code>). Thiết kế nào tránh gọi Claude lặp lại và không mất chữ?", "options": ["Tạo lượt trả lời bằng POST có idempotency key; worker stream từ Claude và ghi từng chunk có id vào Redis; GET SSE đọc từ Redis từ sau <code>Last-Event-ID</code>", "Mỗi lần reconnect gọi lại Claude với cùng prompt", "Tắt reconnect và bắt người dùng tải lại trang", "Lưu stream trong biến toàn cục của một task"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Tách sinh nội dung khỏi phân phối nội dung giúp reconnect chỉ là đọc lại buffer, không phát sinh chi phí model.<br><strong>Vì sao các lựa chọn khác sai:</strong> Gọi lại tốn gấp đôi và câu trả lời có thể khác; tắt reconnect làm UX kém; biến toàn cục không dùng được khi reconnect rơi vào task ECS khác."},
  {"level": 3, "q": "Chatbot vừa trả lời FAQ đơn giản vừa phân tích hợp đồng phức tạp. Ràng buộc: FAQ phải có chữ đầu tiên thật nhanh, phân tích phải chính xác. Chiến lược?", "options": ["Phân loại yêu cầu rồi định tuyến: FAQ dùng <code>claude-haiku-4-5</code> (hoặc effort thấp), phân tích hợp đồng dùng <code>claude-opus-5</code>; cả hai đều stream", "Dùng Opus effort max cho mọi yêu cầu", "Dùng Haiku cho mọi yêu cầu", "Tắt streaming cho FAQ"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Định tuyến theo độ khó cân bằng độ trễ, chi phí và chất lượng.<br><strong>Vì sao các lựa chọn khác sai:</strong> Opus effort max cho FAQ chậm và đắt; Haiku cho mọi việc có thể thiếu chính xác với hợp đồng; tắt streaming làm FAQ chậm hơn về cảm nhận."},
  {"level": 3, "q": "Muốn các lượt \"chat nhanh\" có độ trễ và chi phí thấp hơn mà không đổi model <code>claude-opus-5</code>. Tham số nào phù hợp?<pre><code>await client.messages.stream({\n  model: \"claude-opus-5\",\n  max_tokens: 16000,\n  output_config: { effort: /* ? */ },\n  messages: history,\n}).finalMessage();</code></pre>", "options": ["<code>\"max\"</code>", "<code>\"xhigh\"</code>", "<code>\"low\"</code>: model suy nghĩ ít hơn, trả lời nhanh và tốn ít token hơn", "<code>\"none\"</code>"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> <code>effort</code> điều chỉnh mức đầu tư suy nghĩ/token; mức thấp hợp với câu hỏi đơn giản.<br><strong>Vì sao các lựa chọn khác sai:</strong> <code>max</code>, <code>xhigh</code> tăng suy nghĩ và độ trễ; <code>none</code> không phải giá trị hợp lệ (các mức là low, medium, high, xhigh, max)."},
  {"level": 3, "q": "Giữa hội thoại, người dùng bật \"chế độ trả lời ngắn\". Muốn đổi hành vi mà không phá cache của system prompt dài. Cách nào phù hợp nhất (trên model hỗ trợ)?<pre><code>messages: [\n  ...history,\n  { role: \"user\", content: userMessage },\n  { role: \"system\", content: \"Chế độ ngắn gọn: trả lời dưới 40 từ.\" },\n]</code></pre>", "options": ["Sửa top-level system mỗi khi đổi chế độ", "Prefill lượt assistant \"Ngắn gọn:\"", "Đặt system message ở vị trí <code>messages[0]</code>", "Thêm system message giữa hội thoại (sau lượt user) thay vì sửa top-level <code>system</code>; kiểm tra model có hỗ trợ không (model không hỗ trợ trả 400)"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Mid-conversation system message giữ nguyên tiền tố đã cache và mang quyền của operator.<br><strong>Vì sao các lựa chọn khác sai:</strong> Sửa top-level system làm mất cache toàn bộ; prefill lượt cuối không được hỗ trợ trên model mới; system message không được là <code>messages[0]</code>."},
  {"level": 3, "q": "Next.js chạy trên ECS, người dùng ở Việt Nam, API ở region xa. Ưu tiên của sản phẩm là chữ xuất hiện nhanh. Thay đổi nào có tác động lớn nhất đến trải nghiệm?", "options": ["Đảm bảo stream thông suốt tới trình duyệt (không bị buffer ở proxy/CDN, không nén gom) để chữ đầu tiên đến ngay", "Tăng max_tokens để câu trả lời đầy đủ", "Chuyển sang gọi không stream và hiển thị spinner đẹp hơn", "Lưu lịch sử vào localStorage"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Độ trễ cảm nhận phụ thuộc chủ yếu vào việc chunk đầu tiên có tới client ngay không; buffer ở bất kỳ tầng nào cũng xoá lợi ích streaming.<br><strong>Vì sao các lựa chọn khác sai:</strong> max_tokens không làm nhanh hơn; spinner không thay được chữ thật; nơi lưu lịch sử phía client không ảnh hưởng tốc độ sinh."},
  {"level": 3, "q": "Trong NestJS, hai module <code>ChatModule</code> và <code>ReportModule</code> đều cần client Claude. Cách tổ chức tốt nhất?<pre><code>@Module({\n  providers: [{\n    provide: ANTHROPIC,\n    inject: [ConfigService],\n    useFactory: (cfg: ConfigService) =&gt; new Anthropic({ apiKey: cfg.getOrThrow(\"ANTHROPIC_API_KEY\") }),\n  }],\n  exports: [ANTHROPIC],\n})\nexport class AnthropicModule {}</code></pre>", "options": ["Mỗi request tạo <code>new Anthropic()</code> mới trong controller", "Mỗi module tự đọc key từ file .env bằng fs", "Một <code>AnthropicModule</code> cung cấp một instance dùng chung qua DI; các module khác import nó", "Đặt client trong biến global window"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Provider singleton tái sử dụng kết nối và cấu hình tập trung (key từ Secrets Manager được inject vào env của task).<br><strong>Vì sao các lựa chọn khác sai:</strong> Tạo client mỗi request lãng phí và phân tán cấu hình; tự đọc .env bỏ qua ConfigService; <code>window</code> không tồn tại trên server."},
  {"level": 3, "q": "Một số hội thoại vượt context window và bị 400. Yêu cầu: không mất ngữ cảnh gần nhất, không chặn người dùng. Thứ tự xử lý hợp lý?", "options": ["Đếm token trước khi gửi; nếu vượt ngưỡng an toàn thì tóm tắt/compaction phần cũ, giữ nguyên các lượt gần nhất, rồi mới gọi API", "Bắt lỗi 400 rồi xoá toàn bộ lịch sử", "Tăng max_tokens để chứa đủ", "Chia câu hỏi thành nhiều request song song"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Chủ động đo và rút gọn trước khi gửi tránh lỗi mà vẫn giữ ngữ cảnh mới nhất.<br><strong>Vì sao các lựa chọn khác sai:</strong> Xoá toàn bộ làm mất ngữ cảnh; max_tokens là giới hạn output, không mở rộng context; chia song song phá mạch hội thoại."},
  {"level": 3, "q": "Workflow nightly chạy bộ \"replay\" 50 hội thoại mẫu để phát hiện hồi quy khi đổi prompt. Thiết kế nào hợp lý?<pre><code>on:\n  schedule: [{ cron: \"0 19 * * *\" }]\n  workflow_dispatch:\njobs:\n  replay:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - run: pnpm install --frozen-lockfile\n      - run: pnpm --filter api eval:replay\n        env:\n          ANTHROPIC_API_KEY: ${{ secrets.ANTHROPIC_API_KEY }}</code></pre>", "options": ["Sai, phải chạy trên mọi pull_request từ fork", "Sai, secret phải echo ra log để debug", "Sai, cron không dùng được trong GitHub Actions", "Hợp lý: chạy theo lịch với secret, không chạy mỗi PR từ fork; kết quả so sánh với tiêu chí chấm để phát hiện hồi quy"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Eval gọi API thật tốn chi phí nên chạy định kỳ hoặc thủ công; secret chỉ có trong ngữ cảnh tin cậy.<br><strong>Vì sao các lựa chọn khác sai:</strong> Fork PR không có secret và không nên có; không in secret ra log; <code>schedule</code> với cron là trigger hợp lệ."},
  {"level": 3, "q": "Service NestJS chạy trong Lambda cần stream trực tiếp tới trình duyệt. Lựa chọn nào khả thi, có lưu ý?", "options": ["API Gateway REST mặc định stream được mọi response", "Lambda không bao giờ stream được, bắt buộc WebSocket", "Dùng Lambda response streaming qua Function URL (runtime Node.js hỗ trợ), hoặc chuyển phần chat streaming sang ECS; kiểm tra tài liệu AWS mới nhất về giới hạn", "Chỉ cần trả Observable từ handler Lambda"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Lambda có chế độ response streaming cho Function URL; ECS phù hợp hơn cho kết nối dài.<br><strong>Vì sao các lựa chọn khác sai:</strong> Không nên mặc định API Gateway REST stream được; WebSocket không phải lựa chọn bắt buộc; Observable của NestJS không tự thành response streaming của Lambda."},
  {"level": 3, "q": "Team muốn \"ép Claude tiếp tục bằng tiếng Việt\" bằng cách thêm lượt assistant cuối <code>\"Dạ, \"</code> trên <code>claude-opus-5</code>. Kết quả và cách thay thế?", "options": ["Chạy tốt và rẻ hơn", "Chỉ lỗi khi stream", "Chạy tốt nếu dùng temperature 0", "Prefill lượt assistant cuối không được hỗ trợ trên model mới (400); đặt yêu cầu ngôn ngữ trong system prompt"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Model mới bỏ hỗ trợ prefill ở lượt cuối; chỉ dẫn rõ trong system prompt là cách chuẩn.<br><strong>Vì sao các lựa chọn khác sai:</strong> Request bị từ chối nên không \"chạy tốt\"; lỗi xảy ra dù stream hay không; temperature không liên quan."},
  {"level": 3, "q": "Hội thoại lưu trong PostgreSQL, API <code>GET /conversations/:id/messages</code> trả toàn bộ lịch sử. Ai đó đổi <code>:id</code> và đọc được hội thoại người khác. Sửa đúng?", "options": ["Dùng cuid thay uuid là đủ", "Kiểm tra quyền sở hữu ở NestJS (guard/service: <code>where: { id, userId: req.user.id }</code>) cho mọi endpoint đọc/ghi lịch sử", "Mã hoá id trong URL bằng base64", "Chỉ ẩn nút ở frontend"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Lịch sử hội thoại là dữ liệu nhạy cảm; kiểm soát truy cập phải ở server theo người dùng đã xác thực.<br><strong>Vì sao các lựa chọn khác sai:</strong> Id khó đoán không thay được phân quyền; base64 chỉ là mã hoá dễ đảo ngược; ẩn nút ở frontend không chặn gọi API trực tiếp."},
  {"level": 3, "q": "Stream đã gửi 300 chữ tới trình duyệt thì gặp lỗi <code>overloaded</code> giữa chừng. Cách xử lý đúng?<pre><code>s.on(\"error\", (err) =&gt; {\n  controller.enqueue(encoder.encode(`data: ${JSON.stringify({ type: \"error\", retryable: true })}\\n\\n`));\n  controller.close();\n});</code></pre>", "options": ["Gửi sự kiện lỗi có cấu trúc cho client, không lưu lượt dở như câu trả lời hoàn chỉnh, cho người dùng (hoặc client) thử lại cả lượt", "Tự gọi lại API và nối tiếp chữ mới vào sau 300 chữ cũ", "Im lặng đóng kết nối để client tưởng đã xong", "Lưu 300 chữ vào lịch sử như câu trả lời đầy đủ rồi kết thúc"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Khi một phần chữ đã tới người dùng, không thể retry trong suốt; lỗi giữa stream cần được báo rõ để UI quyết định thử lại cả lượt.<br><strong>Vì sao các lựa chọn khác sai:</strong> Gọi lại sinh câu trả lời mới từ đầu, nối vào chữ cũ gây lặp và rối; đóng im lặng khiến người dùng nhận câu trả lời cụt; lưu lượt dở như bản hoàn chỉnh làm sai ngữ cảnh lượt sau."}
];
